    // A-R14, A-Q4, scenariusz 16 (bez daty wydania ważność liczona względem dziś, NO_HANDOVER_DATE na końcu)
    @Test
    void reportsExpiredAgainstTodayAndNoHandoverDateLastWhenHandoverDateMissing() {
        givenVehicle(null, false);
